import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { checkSanction, getSanctionError } from "@/lib/sanction-utils";
import { tmdbGet } from "@/lib/tmdb";
import { getAnimeDetailFromKitsu, anilistFetch } from "@/lib/anilist";
import { createClient as createServerClient } from "@/lib/supabase/server";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);
const supabaseAdmin = createClient(supabaseUrl, process.env.SUPABASE_SERVICE_ROLE_KEY!);

const VALID_STATUSES = ["watching", "completed", "plan_to_watch", "on_hold", "dropped"];

import { resolveUsername, resolveAuthUid } from "@/lib/auth-helper";

// ─── GET: fetch tracking list ───
export async function GET(req: NextRequest) {
  const username = await resolveUsername(req);
  const { searchParams } = new URL(req.url);
  const status = searchParams.get("status");

  if (!username) {
    return NextResponse.json({ error: "Missing username" }, { status: 400 });
  }

  const userId = await resolveAuthUid(req);
  if (!userId) {
    return NextResponse.json([]);
  }

  // Use the server session client so RLS (auth.uid() = username) applies
  // and returns only the authenticated user's own rows.
  const serverSupabase = await createServerClient();
  let query = serverSupabase
  .from("media_trackings")
  .select("*")
  .eq("username", userId)
  .order("updated_at", { ascending: false });

  const seasonNumber = searchParams.get("seasonNumber");
  if (seasonNumber !== null) {
  query = query.eq("season_number", parseInt(seasonNumber));
  }

  if (status) {
    query = query.eq("status", status);
  }

  const { data, error } = await query;

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  return NextResponse.json(
    (data || []).map((t) => ({
      id: t.id,
      username,
      userId: t.username,
      tmdbId: t.tmdb_id,
      anilistId: t.anilist_id,
      mediaType: t.media_type,
      seasonNumber: t.season_number,
      status: t.status,
      rating: t.rating,
      progress: t.progress,
      updatedAt: t.updated_at,
    }))
  );
}

// ─── POST: upsert tracking ───
export async function POST(req: NextRequest) {
  try {
    const username = await resolveUsername(req);
    if (!username) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    // Sanction check
    const sanction = await checkSanction(username);
    const sanctionErr = getSanctionError(sanction, "write");
    if (sanctionErr) return NextResponse.json({ error: sanctionErr }, { status: 403 });

    const body = await req.json();
    const { tmdbId, mediaType, status, rating, progress, seasonNumber } = body;

    if (tmdbId == null || !mediaType || !status) {
      return NextResponse.json(
        { error: "Missing required fields: tmdbId, mediaType, status" },
        { status: 400 }
      );
    }

    if (!VALID_STATUSES.includes(status)) {
      return NextResponse.json(
        { error: `Invalid status. Must be: ${VALID_STATUSES.join(", ")}` },
        { status: 400 }
      );
    }

    const userId = await resolveAuthUid(req);
    if (!userId) {
      return NextResponse.json({ error: "Failed to resolve user" }, { status: 500 });
    }

    // Use the session client so RLS (auth.uid() = username) lets the user
    // write only their own rows — this is the correct, secure path.
    const serverSupabase = await createServerClient();

    const sn = seasonNumber ?? 0;

    // Preserve existing watched_at — only set on first completion
    const existingWatchDate = status === "completed"
      ? ((await serverSupabase
          .from("media_trackings")
          .select("watched_at")
          .eq("username", userId)
          .eq("tmdb_id", tmdbId)
          .eq("media_type", mediaType)
          .eq("season_number", sn)
          .maybeSingle())?.data?.watched_at ?? undefined)
      : undefined;

    let posterUrl = body.posterUrl || null;
    let title = body.title || null;
    const yearVal = body.year || null;
    const tmdbRating = body.tmdbRating || null;

    // ── Integrity guard: reject track requests for titles we can't resolve. ──
    // If the client sent NO metadata (no title AND no poster), the row would be
    // stored as a dead shell ("Untitled", no poster, TMDB 404). Verify the title
    // really exists before writing, so a bogus/non-existent TMDB/AniList id can't
    // create an unresolvable watching/completed shell in the library.
    if (!title && !posterUrl) {
      const meta = await fetchMetadata(tmdbId, mediaType);
      if (!meta.title) {
        return NextResponse.json(
          { error: "Could not resolve this title — it may have been removed or doesn't exist." },
          { status: 422 }
        );
      }
      // Keep the resolved metadata so the row is never stored without a title.
      if (!posterUrl) posterUrl = meta.poster;
      if (!title) title = meta.title;
    }

    const upsertData: Record<string, unknown> = {
      username: userId,
      tmdb_id: tmdbId,
      media_type: mediaType,
      season_number: sn,
      status,
      rating: rating ?? null,
      progress: progress ?? null,
      poster_url: posterUrl,
      title,
      year: yearVal,
      tmdb_rating: tmdbRating,
      updated_at: new Date().toISOString(),
    };
    // Set watched_at only on first completion (existingWatchDate is null or undefined)
    if (status === "completed" && !existingWatchDate) {
      upsertData.watched_at = new Date().toISOString();
    } else if (status === "completed" && existingWatchDate) {
      upsertData.watched_at = existingWatchDate;
    }

    const { data, error } = await serverSupabase
      .from("media_trackings")
      .upsert(upsertData, { onConflict: "username,tmdb_id,media_type,season_number" })
      .select("*")
      .single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Invalidate cached stats for this user
    void supabaseAdmin
      .from("user_stats_cache")
      .delete()
      .eq("username", username.trim().slice(0, 20))
      .then(() => {}, () => {});

    // Fetch & store metadata if not provided by client (non-blocking)
    if (!posterUrl || !title) {
      (async () => {
        try {
          const meta = await fetchMetadata(tmdbId, mediaType);
          const updates: Record<string, unknown> = {};
          if (!posterUrl && meta.poster) updates.poster_url = meta.poster;
          if (!title && meta.title) updates.title = meta.title;
          if (!yearVal && meta.year) updates.year = meta.year;
          if (!tmdbRating && meta.rating) updates.tmdb_rating = meta.rating;
          if (Object.keys(updates).length > 0) {
            await serverSupabase.from("media_trackings").update(updates).eq("id", data.id);
          }
        } catch {}
      })();
    }

    return NextResponse.json({
      id: data.id,
      username: username.trim().slice(0, 20),
      userId: data.username,
      tmdbId: data.tmdb_id,
      anilistId: data.anilist_id,
      mediaType: data.media_type,
      seasonNumber: data.season_number,
      status: data.status,
      rating: data.rating,
      progress: data.progress,
      updatedAt: data.updated_at,
    });
  } catch {
    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  }
}

// Helper: fetch metadata from TMDB/AniList
async function fetchMetadata(tmdbId: number, mediaType: string): Promise<{poster: string|null, title: string|null, year: number|null, rating: number|null}> {
  try {
    if (mediaType === "anime") {
      const res = await anilistFetch(`query($id:Int){Media(id:$id){title{romaji english}coverImage{extraLarge}startDate{year}averageScore}}`, { id: tmdbId });
      if (res.ok) {
        const j = await res.json();
        const m = j.data?.Media;
        return {
          poster: m?.coverImage?.extraLarge || null,
          title: m?.title?.english || m?.title?.romaji || null,
          year: m?.startDate?.year || null,
          rating: m?.averageScore ? Math.round(m.averageScore) / 10 : null,
        };
      }
      // AniList down — fall back to Kitsu for title/poster/year/rating
      const kd = await getAnimeDetailFromKitsu(tmdbId);
      if (kd) {
        return {
          poster: kd.poster || null,
          title: kd.title || null,
          year: kd.year || null,
          rating: kd.rating || null,
        };
      }
    } else {
      const ep = mediaType === "tv" ? "tv" : "movie";
      const d = await tmdbGet(`/${ep}/${tmdbId}`);
      return {
        poster: d.poster_path ? `https://image.tmdb.org/t/p/w500${d.poster_path}` : null,
        title: d.title || d.name || null,
        year: parseInt((d.release_date || d.first_air_date || "").slice(0, 4)) || null,
        rating: d.vote_average ? Math.round(d.vote_average * 10) / 10 : null,
      };
    }
  } catch {}
  return { poster: null, title: null, year: null, rating: null };
}

// ─── DELETE: remove tracking ───
export async function DELETE(req: NextRequest) {
  try {
    const username = await resolveUsername(req);
    if (!username) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    // Sanction check
    const sanction = await checkSanction(username);
    const sanctionErr = getSanctionError(sanction, "write");
    if (sanctionErr) return NextResponse.json({ error: sanctionErr }, { status: 403 });

    const body = await req.json();
    const { tmdbId, mediaType, seasonNumber } = body;

    if (tmdbId == null || !mediaType) {
      return NextResponse.json(
        { error: "Missing required fields: username, tmdbId, mediaType" },
        { status: 400 }
      );
    }

    const userId = await resolveAuthUid(req);
    if (!userId) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const sn = seasonNumber ?? 0;

    const serverSupabase = await createServerClient();
    const { error } = await serverSupabase
      .from("media_trackings")
      .delete()
      .eq("username", userId)
      .eq("tmdb_id", tmdbId)
      .eq("media_type", mediaType)
      .eq("season_number", sn);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Invalidate cached stats for this user
    void supabaseAdmin
      .from("user_stats_cache")
      .delete()
      .eq("username", username.trim().slice(0, 20))
      .then(() => {}, () => {});

    return NextResponse.json({ success: true });
  } catch {
    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  }
}
